// Settings of the API, read from the environment (see .env.example).

import Foundation
import Vapor

/// Settings of the API. The tests build their own.
struct Settings: Sendable {
    /// Connection URL of the database (DATABASE_URL)
    var databaseURL = "sqlite://app.db"
    /// Accepted API keys (API_KEYS, separated by commas)
    var apiKeys: [String] = []

    static func fromEnvironment() -> Settings {
        let read = { (name: String) -> String? in Environment.get(name).flatMap { $0.isEmpty ? nil : $0 } }
        var settings = Settings()
        if let value = read("DATABASE_URL") { settings.databaseURL = value }
        settings.apiKeys = (read("API_KEYS") ?? "").split(separator: ",").map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
        return settings
    }
}

