// Wires the API: errors, storage, services and routes.

import Fluent
import Vapor

/// Builds the API with its settings: the app that the entry point runs and the tests call.
func configure(_ app: Application, settings: Settings) async throws {
    app.routes.defaultMaxBodySize = "1mb"
    // The error format of the API replaces Vapor's
    app.middleware = Middlewares()
    app.middleware.use(ApiErrorMiddleware())
    // Creates the tables that are missing, while you develop
    try useDatabase(app, url: settings.databaseURL)
    try await app.autoMigrate()
    let security = await Security.make(settings)

    let customerRepository: any CustomerRepository = FluentCustomerRepository(database: app.db)
    let productRepository: any ProductRepository = FluentProductRepository(database: app.db)
    let orderRepository: any OrderRepository = FluentOrderRepository(database: app.db)
    let customerService = CustomerService(repository: customerRepository)
    let productService = ProductService(repository: productRepository)
    let orderService = OrderService(repository: orderRepository, customerRepository: customerRepository, productRepository: productRepository)
    try app.register(collection: CustomerController(service: customerService, security: security))
    try app.register(collection: ProductController(service: productService, security: security))
    try app.register(collection: OrderController(service: orderService, security: security))
}

