// The database of the API: its connection and its tables, one per resource.

import Fluent
import FluentSQL
import FluentSQLiteDriver
import Vapor

/// A DATABASE_URL this API cannot use.
struct DatabaseURLError: Error, CustomStringConvertible {
    let description: String
}

/// Connects to the database of DATABASE_URL (sqlite://<file>) and adds the migrations of
/// every table. The application runs them when it starts, while you develop; use your own for a real database.
func useDatabase(_ app: Application, url: String) throws {
    if url.hasPrefix("sqlite://") {
        app.databases.use(.sqlite(.file(String(url.dropFirst("sqlite://".count)))), as: .sqlite)
    } else {
        throw DatabaseURLError(description: "DATABASE_URL is not a database this API uses: \(url)")
    }
    app.migrations.add(CustomerMigration(), ProductMigration(), OrderMigration())
}

/// Sorts the rows without a value last, whatever the order.
func nullsLast(_ column: String) -> DatabaseQuery.Sort {
    .sql(SQLBinaryExpression(left: SQLColumn(column), op: SQLBinaryOperator.is, right: SQLLiteral.null))
}

