// Where customers are kept.

import Fluent
import Foundation

/// What a list of customers can filter by: a field that has a value must be equal to it.
struct CustomerFilters: Sendable {
    var name: String?
    var email: String?
}

/// Where customers are kept. The service depends only on this protocol.
protocol CustomerRepository: Sendable {
    /// Items equal to every filter, in order, within the window; and how many match.
    func list(_ query: ListQuery<CustomerFilters>) async throws -> ListResult<Customer>

    /// The item with this key, or nil when there is none.
    func get(_ key: Int64) async throws -> Customer?

    /// Stores a new item and assigns its key; returns it as stored.
    func add(_ item: Customer) async throws -> Customer

    /// Stores the new state of an existing item and returns it.
    func update(_ item: Customer) async throws -> Customer

    /// Removes an existing item.
    func delete(_ key: Int64) async throws
}

/// Keeps customers in the database with Fluent.
struct FluentCustomerRepository: CustomerRepository {
    let database: any Database

    func list(_ query: ListQuery<CustomerFilters>) async throws -> ListResult<Customer> {
        let select = CustomerRecord.query(on: database)
        if let value = query.filters.name {
            select.filter(\.$name == value)
        }
        if let value = query.filters.email {
            select.filter(\.$email == value)
        }
        let total = try await select.copy().count()
        let direction: DatabaseQuery.Sort.Direction = query.descending ? .descending : .ascending
        // Items without a value go last, whatever the order; the key breaks ties
        switch query.sortField {
        case "name":
            select.sort(nullsLast("name")).sort(\.$name, direction)
        case "email":
            select.sort(nullsLast("email")).sort(\.$email, direction)
        default:
            break
        }
        select.sort(\.$id).offset(query.offset)
        if let limit = query.limit {
            select.limit(limit)
        }
        return ListResult(items: try await select.all().map(toItem), total: total)
    }

    func get(_ key: Int64) async throws -> Customer? {
        try await CustomerRecord.find(key, on: database).map(toItem)
    }

    func add(_ item: Customer) async throws -> Customer {
        let record = CustomerRecord()
        write(item, to: record)
        try await record.create(on: database)
        return try toItem(record)
    }

    func update(_ item: Customer) async throws -> Customer {
        guard let record = try await CustomerRecord.find(item.id, on: database) else {
            throw ApiError.notFound("customer")
        }
        write(item, to: record)
        try await record.update(on: database)
        return try toItem(record)
    }

    func delete(_ key: Int64) async throws {
        try await CustomerRecord.query(on: database).filter(\.$id == key).delete()
    }

    /// Every field of an item in its column; the key is set apart.
    private func write(_ item: Customer, to record: CustomerRecord) {
        record.name = item.name
        record.email = item.email
        record.password = item.password
        record.phone = item.phone
        record.address = jsonText(item.address)
        record.createdAt = item.createdAt
    }

    private func toItem(_ record: CustomerRecord) throws -> Customer {
        Customer(
            id: try record.requireID(),
            name: record.name,
            email: record.email,
            password: record.password,
            phone: record.phone,
            address: jsonValue(record.address, as: Address.self),
            createdAt: record.createdAt
        )
    }
}

